import{_ as e,a as s,b as r,c as a}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as i,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const y=JSON.parse('{"title":"Presets","description":"MiniTavern prompt presets — basic prompts plus a sortable prompt list. Sampling stays in model settings.","frontmatter":{"title":"Presets","description":"MiniTavern prompt presets — basic prompts plus a sortable prompt list. Sampling stays in model settings.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Presets · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern prompt presets — basic prompts plus a sortable prompt list. Sampling stays in model settings."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/presets"}]]},"headers":[],"relativePath":"en/manual/presets.md","filePath":"en/manual/presets.md","lastUpdated":1791862671000}'),p={name:"en/manual/presets.md"};function d(c,t,h,m,g,u){return o(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h1><p>Path: bottom <strong>Settings</strong> → <strong>Presets</strong>.</p><p>A preset is a full prompt structure: it changes how roleplay is written and constrained. Temperature and other sampling stay under <strong>Model settings</strong>.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+e+'" alt="Presets entry in Settings"><figcaption>1 · Settings → Presets</figcaption></figure><figure class="shot-step"><img src="'+s+'" alt="Preset list"><figcaption>2 · List and New</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="Edit a preset"><figcaption>3 · Name, basic prompts, prompt list</figcaption></figure><figure class="shot-step"><img src="'+a+'" alt="New prompt"><figcaption>4 · New prompt</figcaption></figure></div><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><ol><li><strong>New</strong> can create a preset or import a SillyTavern Chat Completion preset. Sampling keys are ignored, with a note to set them in Model settings.</li><li>A fresh install has only the row tagged <strong>Default</strong>. It cannot be edited or deleted.</li><li>The menu on a row can move it to the top, set it as default, edit, duplicate, export, or delete.</li><li>Create and duplicate open the editor first. The row appears in the list only after <strong>Save</strong>.</li></ol><h2 id="edit-a-preset" tabindex="-1">Edit a preset <a class="header-anchor" href="#edit-a-preset" aria-label="Permalink to &quot;Edit a preset&quot;">​</a></h2><ul><li><strong>Name</strong> is required.</li><li><strong>Basic prompts</strong> covers persona, character description, personality, scenario, example-chat start, new-chat start, and lorebook.</li><li>The <strong>Prompts</strong> list can be searched. Long-press to reorder. Entries with the switch on are used for a normal send; switched-off entries stay inactive and are not injected.</li><li><strong>Add</strong> opens a new prompt. Custom entries can be edited, duplicated, and deleted. Built-in entries only allow name and content.</li></ul><p>A character card’s main prompt and post-history instructions override the matching preset entries. Scenario text uses chat settings first, then the card, then plain text in the preset’s basic prompts.</p><p>Continue, regenerate, and smart reply do not read this preset. A normal send assembles prompts in list order.</p><h2 id="new-prompt" tabindex="-1">New prompt <a class="header-anchor" href="#new-prompt" aria-label="Permalink to &quot;New prompt&quot;">​</a></h2><ol><li><strong>Name</strong> is required.</li><li><strong>Role</strong> starts as SYSTEM and can be changed.</li><li><strong>Injection position</strong> <strong>Relative</strong> inserts the prompt at its place in the list. <strong>In-chat</strong> shows <strong>Injection depth</strong> and inserts it into history at that depth.</li><li><strong>Content</strong> is the prompt text. Macros work here.</li><li><strong>Save</strong> returns to the preset editor.</li></ol><h2 id="this-chat-only" tabindex="-1">This chat only <a class="header-anchor" href="#this-chat-only" aria-label="Permalink to &quot;This chat only&quot;">​</a></h2><p>Path: conversation → <strong>Chat settings</strong> → model → <strong>Presets</strong>.</p><p><strong>Follow default preset</strong> is on by default. Turn it off to pick another preset for this chat only.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./model-link">Model link</a>: sampling stays in model settings</li><li><a href="./persona">Persona</a> · <a href="./lorebook">Lorebook</a>: basic prompts can pull them in</li></ul>',18)])])}const _=i(p,[["render",d]]);export{y as __pageData,_ as default};
